import{z as i,x as s,o as B,c as d,q as r,j as t,D as o,d as e,s as n,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"家庭生产与时间利用","description":"","frontmatter":{"title":"家庭生产与时间利用","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/household-production.md","filePath":"econ/household-production.md","lastUpdated":1791063341000}'),p={name:"econ/household-production.md"};function D(h,E,u,c,C,m){const A=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="家庭生产与时间利用" tabindex="-1">家庭生产与时间利用 <a class="header-anchor" href="#家庭生产与时间利用" aria-label="Permalink to &quot;家庭生产与时间利用&quot;">​</a></h1><div class="epigraph"><p>GDP 看不见的半边天：做饭、带娃、照护老人——家庭不是消费黑箱，是一座没进账本的工厂。</p><footer>—— 据 Becker「A Theory of the Allocation of Time」(1965)；Gronau 家庭生产模型 (1977)</footer></div><p><a href="/econ/capability-approach">可行能力方法</a>把福祉的镜头从收入拉宽，本课把镜头对准 GDP 的测量盲区：家庭内部的生产活动。缺口是<strong>时间配置模型</strong>——在市场工作、家务生产与闲暇之间，人怎么分配一天 24 小时。它是女性劳动参与、育儿成本与 GDP 卫星账户的共同地基。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自己做饭与外卖做饭，GDP 一个不计一个计；妻子退出职场回家带娃，GDP「下降」。国民账户把家庭当纯消费单位，掩盖了规模可观的非市场生产——OECD 卫星账户估计其价值达 GDP 的 30–50%。要回答：家庭生产怎么进模型，它的机会成本怎么定价，技术进步（洗衣机、外卖）怎么改写时间配置。</p><p><span class="marginnote">术语翻译：家庭生产函数 \\(Z=f(x_M, x_T)\\)——市场品 \\(x_M\\)（食材）与家庭时间 \\(x_T\\)（做饭）合成为家庭品 \\(Z\\)（一顿饭）；全收入（full income）= 货币收入 + 全部时间的影子价格。</span></p><p><span class="marginnote">数字实例：煮一餐饭食材 30 元 + 45 分钟。时薪 100 元的人的机会成本 75 元，总成本 105 元；时薪 30 元的人 22.5 元，总成本 52.5 元——同一顿饭，市场价格相同，「真实价格」差一倍，替代行为（叫外卖与否）随之分岔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Gronau 模型把时间分三块：市场工作 \\(N\\)、家务 \\(H\\)、闲暇 \\(L\\)。边际条件：时间从家务转向市场工作直到「家务边际产品 × 家庭品影子价格 = 市场工资」。推论直接：市场工资上升 ⇒ 家务时间下降（外包部分家务）；家庭生产率提升（洗衣机）⇒ 既解放时间又降低 \\(Z\\) 的影子价格。GDP 卫星账户的方法论之争全在第三步：产出法（按替代成本估价服务量）还是投入法（按机会成本估价工时）。</p>',9)),(B(),t(l,null,{default:o(()=>[n(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%80%E5%A4%A9%2024h%22%5D%20--%3E%20B%5B%22%E5%B8%82%E5%9C%BA%E5%B7%A5%E4%BD%9C%20N%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%AE%B6%E5%8A%A1%E7%94%9F%E4%BA%A7%20H%22%5D%0A%20%20A%20--%3E%20D%5B%22%E9%97%B2%E6%9A%87%20L%22%5D%0A%20%20C%20--%3E%20E%5B%22%E5%AE%B6%E5%BA%AD%E7%94%9F%E4%BA%A7%E5%87%BD%E6%95%B0%20Z%3Df(%E5%93%81%2C%20%E6%97%B6)%22%5D%0A%20%20E%20--%3E%20F%7B%22%E8%BE%B9%E9%99%85%E6%AF%94%E8%BE%83%22%7D%0A%20%20F%20--%3E%7C%22%E5%AE%B6%E5%8A%A1%E8%BE%B9%E9%99%85%E5%80%BC%20%3E%20%E5%B7%A5%E8%B5%84%22%7C%20G%5B%22%E5%A4%9A%E5%81%9A%E5%AE%B6%E5%8A%A1%22%5D%0A%20%20F%20--%3E%7C%22%E5%B7%A5%E8%B5%84%20%3E%20%E5%AE%B6%E5%8A%A1%E8%BE%B9%E9%99%85%E5%80%BC%22%7C%20H%5B%22%E5%A4%96%E5%8C%85%2F%E4%B8%8A%E7%8F%AD%22%5D%0A%20%20G%20--%3E%20I%5B%22%E6%97%B6%E9%97%B4%E9%85%8D%E7%BD%AE%E5%9D%87%E8%A1%A1%22%5D%0A%20%20H%20--%3E%20I%0A"})]),fallback:o(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：家是「一揽子小微工厂」，车间主任是时间。工资涨了，主任把劳动密集车间（做饭、保洁）外包，只保留技术密集车间（育儿陪伴）；洗衣机像一次车间自动化——不是把车间关闭，而是让同一小时产出翻倍。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("模型解释三大实证谜题。"),a("strong",null,"性别工资差与家务分工"),e("：即使控制市场工资，女性家务时间仍系统性偏高——社会规范的影子价格进入家庭生产函数，市场工资平等化未必自动带来家务平等（「第二班」）。"),a("strong",null,"劳动供给的背面"),e("：已婚女性劳动参与率上升与家电普及、育儿市场化同步——技术替代弹性决定外包速度。"),a("strong",null,"福利测量"),e("：的机会成本随生命阶段变动，只看市场收入的贫困线会误判多孩家庭。机制核心一句话：时间是家庭唯一的硬约束，一切家庭决策都是它在三个出口间的套利。")],-1)),(B(),t(l,null,{default:o(()=>[n(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%B4%97%E8%A1%A3%E6%9C%BA%E6%94%B9%E5%8F%98%E4%BA%86%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20R%5B%22%E5%AE%B6%E5%8A%A1%E7%94%9F%E4%BA%A7%E7%8E%87%E2%86%91%22%5D%0A%20%20R%20--%3E%20S%5B%22%E5%90%8C%E4%B8%80%20Z%20%E9%9C%80%E6%97%B6%E6%9B%B4%E5%B0%91%22%5D%0A%20%20S%20--%3E%20T%5B%22%E9%87%8A%E6%94%BE%E6%97%B6%E9%97%B4%20%E2%86%92%20%E5%B8%82%E5%9C%BA%E5%B7%A5%E4%BD%9C%20or%20%E9%97%B2%E6%9A%87%22%5D%0A%20%20U%7B%22%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%E6%80%8E%E4%B9%88%E5%AE%9A%3F%22%7D%20--%3E%20V%5B%22%E6%9B%BF%E4%BB%A3%E6%88%90%E6%9C%AC%3A%20%E4%BF%9D%E5%A7%86%E5%B7%A5%E8%B5%84%22%5D%0A%20%20U%20--%3E%20W%5B%22%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%3A%20%E6%9C%AC%E4%BA%BA%E5%B7%A5%E8%B5%84%22%5D%0A%20%20V%20--%3E%20X%5B%22%E5%8D%AB%E6%98%9F%E8%B4%A6%E6%88%B7%E4%B8%A4%E5%A4%A7%E6%B5%81%E6%B4%BE%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:o(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：把家务时间乘以平均工资当家庭生产价值——高估（多数家务不需本家时薪水平技能）；反向误区是「家务无价值所以不核算」——OECD 卫星账户证明它占 30–50% GDP，忽略它会系统性误判税收、育儿与养老政策的分配后果。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型的边界：家庭内部谈判被简化——集体家庭模型（Chiappori）把夫妻决策从单一效用拆成讨价还价，解释了「同家庭不同品味」；照护的不可外包性（情感劳动）限制替代逻辑；测量上时间利用调查是唯一数据源，且「陪玩的快乐」算闲暇还是生产存在本质含糊。政策接口：育儿成本核算、照护假定价、退休后家庭生产低估导致的养老误判。与<a href="/econ/fertility-econ">生育的经济学</a>衔接：孩子是家庭生产函数里时间最密集的「产品」，质量-数量替代全在这一框架内展开。</p><p><span class="marginnote">直觉类比：GDP 是只记门店流水、无视后厨的账本；家庭生产核算就是给后厨装摄像头——不改变菜的味道，但让「谁在掌勺、掌了多久」第一次进入成本表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>家庭是生产单位：市场品 × 时间 → 家庭品；时间是硬约束。</li><li>边际条件「家务边际值 = 市场工资」驱动外包与劳动供给。</li><li>卫星账户产出法/投入法之争照进政策：照护、育儿、养老都受其定价影响。</li><li>出处：Becker 1965；Gronau 1977；Chiappori 集体模型 1992；OECD Household Production Satellite Accounts。</li></ul>',6))])}const P=i(p,[["render",D]]);export{_ as __pageData,P as default};
